const DefaultSort = () => {
  const theme = useTheme() as CoreUITheme;
  const defaultSortData = [
    {
      label: 'Success',
      data: [
        ['AZ', 15],
        ['BB', 10],
        ['CC', 25],
        ['DD', 18],
        ['AA', 22],
        ['EE', 15],
      ],
    },
    {
      label: 'Failed',
      data: [
        ['AZ', 8],
        ['BB', 1],
        ['CC', 3],
        ['DD', 1],
        ['AA', 5],
        ['EE', 5],
      ],
    },
  ] as const;
  const customSort: BarchartSortFn<typeof defaultSortData> = (
    pointA,
    pointB,
  ) => {
    const totalA = pointA.Success + pointA.Failed;
    const totalB = pointB.Success + pointB.Failed;
    return totalA - totalB > 0 ? -1 : totalA - totalB < 0 ? 1 : 0; // Descending order
  };
  return (
    <ChartLegendWrapper
      colorSet={{
        Success: theme.statusHealthy,
        Failed: theme.statusCritical,
      }}
      sortOrder="status"
    >
      <Barchart
        type={{ type: 'category' }}
        stacked
        bars={defaultSortData}
        defaultSort={customSort}
        title="Default Sort"
      />
    </ChartLegendWrapper>
  );
};

const WithCustomTooltip = () => {
  const theme = useTheme() as CoreUITheme;
  const exampleData = [
    {
      label: 'Success',
      data: [
        ['category1', 2],
        ['category2', 4],
        ['category3', 6],
      ],
    },
    {
      label: 'Failed',
      data: [
        ['category1', 8],
        ['category2', 10],
        ['category3', 12],
      ],
    },
  ] as const;
  const customTooltip: BarchartTooltipFn<typeof exampleData> = (pointA) => {
    return (
      <Stack
        direction="vertical"
        gap="r4"
        style={{
          width: '150px',
          backgroundColor: 'black',
          padding: '10px',
          borderRadius: '10px',
          color: 'white',
        }}
      >
        <Text style={{ textAlign: 'center', color: 'white' }}>
          {pointA.category}
        </Text>
        {pointA.values.map((point) => (
          <Text
            key={point.label}
            isEmphazed={point.isHovered}
            style={{
              color: point.isHovered ? 'yellow' : 'white',
            }}
          >
            <Wrap>
              <span>{point.label}:</span>
              <span>{point.value}</span>
            </Wrap>
          </Text>
        ))}
      </Stack>
    );
  };
  return (
    <Stack direction="vertical" gap="r16">
      <Text variant="Large">External Tooltip & Sort Functions</Text>
      <Text variant="Basic" color="textSecondary">
        Tooltip and sort functions defined outside with full type safety
      </Text>
      <ChartLegendWrapper
        colorSet={{
          Success: theme.statusHealthy,
          Failed: theme.statusCritical,
        }}
        sortOrder="status"
      >
        <Stack direction="vertical" gap="r16">
          <Barchart
            title="Custom Tooltip"
            type={{ type: 'category' }}
            bars={exampleData}
            tooltip={customTooltip}
            height={300}
          />
          <ChartLegend shape="line" />
        </Stack>
      </ChartLegendWrapper>
    </Stack>
  );
};

const StatusColors = () => {
  const theme = useTheme() as CoreUITheme;
  const statusData = [
    {
      label: 'Success Rate',
      data: [
        ['API', 95],
        ['Database', 87],
        ['Queue', 92],
      ],
    },
    {
      label: 'Failed Requests',
      data: [
        ['API', 5],
        ['Database', 13],
        ['Queue', 8],
      ],
    },
    {
      label: 'Warning Events',
      data: [
        ['API', 2],
        ['Database', 4],
        ['Queue', 1],
      ],
    },
  ] as const;
  return (
    <ChartLegendWrapper
      colorSet={{
        'Success Rate': theme.statusHealthy,
        'Failed Requests': theme.statusCritical,
        'Warning Events': theme.statusWarning,
      }}
      sortOrder={(a, b) => {
        const statusOrder: Record<string, number> = {
          'Success Rate': 0,
          'Warning Events': 1,
          'Failed Requests': 2,
