const asyncTable = ({}) => {
  function DataComponent({
    data,
    loading,
    row,
  }: {
    row: Row<Entry>;
    loading: boolean;
    data: string;
  }) {
    return loading ? (
      <span>loading ...</span>
    ) : (
      <span> {`${row.values.firstName} ${data}`} </span>
    );
  }

  function RowAsync({ row }: { row: Row<Entry> }) {
    const [loading, setLoading] = React.useState(true);
    const [data, setData] = React.useState('');
    React.useEffect(() => {
      const timer = setTimeout(() => {
        setData('loaded async');
        setLoading(false);
      }, 1000);
      return () => {
        clearTimeout(timer);
      };
    }, []);
    return <DataComponent row={row} loading={loading} data={data} />;
  }

  const renderRowSubComponent = React.useCallback(
    ({ row, ...rest }: CellProps<Entry>) => {
      return <RowAsync row={row} />;
    },
    [],
  );
  const columnAsync: Column<Entry>[] = [
    {
      Header: 'First Name',
      accessor: 'firstName',
      cellStyle: {
        textAlign: 'left',
        width: 'unset',
        flex: 1,
      },
      Cell: renderRowSubComponent,
    },
    {
      Header: 'Last Name',
      accessor: 'lastName',
      cellStyle: {
        textAlign: 'left',
        width: 'unset',
        flex: 1,
      },
    },
    {
      Header: 'Age',
      accessor: 'age',
      cellStyle: {
        textAlign: 'left',
        width: 'unset',
        flex: 0.5,
      },
    },
    {
      Header: 'Health',
      accessor: 'health',
      sortType: 'health',
      cellStyle: {
        textAlign: 'left',
        width: 'unset',
        flex: 1,
      },
    },
  ];

  return (
    <>
      <Title>async cell Table</Title>
      <div
        style={{
          height: '300px',
          paddingTop: '20px',
        }}
      >
        <BrowserRouter>
          <Table
            columns={columnAsync}
            data={data}
            defaultSortingKey={'health'}
          >
            <Table.SearchWithQueryParams></Table.SearchWithQueryParams>
            <Table.SingleSelectableContent
              rowHeight="h40"
              separationLineVariant="backgroundLevel3"
              selectedId={'Rodolph Yohann'}
              onRowSelected={action('Table Row Clicked')}
            />
          </Table>
        </BrowserRouter>
      </div>
    </>
  );
};

const OnBottomCallback = ({}) => {
  const columns: Column<{ index: number; value: number }>[] = [
    {
      Header: 'value',
      accessor: 'value',
      cellStyle: {
        textAlign: 'left',
      },
    },
  ];

  const createData = (indexStart = 0) => {
    const data: { index: number; value: number }[] = [];

    for (let i = 0; i < 100; i++) {
      data.push({
        index: indexStart + i,
        value: Math.floor(Math.random() * 1000),
      });
    }

    return data;
  };

  const [randomData, setRandomData] = useState(createData());

  const onBottom = () => {
    action('onBottom');
    setRandomData([...randomData, ...createData(randomData.length)]);
  };

  return (
    <>
      <Title>async cell Table</Title>
      <div
        style={{
          height: '300px',
          paddingTop: '20px',
        }}
      >
        <Table
          columns={columns}
